package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamAppliedPracticalBank1 {
    private const val T = "ගායන ශිල්පය, ශ්‍රව්‍ය විද්‍යාව, ප්‍රායෝගික පරීක්ෂණ හා සෞන්දර්ය රසය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භාරතීය කලා විචාරයේදී හා සංගීතයේදී සඳහන් වන 'නව රස' සංඛ්‍යාව කොපමණද?", "9 කි", "7 කි", "5 කි", "12 කි", "ශෘංගාර, හාස්‍ය, කරුණ, රෞද්‍ර, වීර, භයානක, බීභත්ස, අද්භුත සහ ශාන්ත යනු නව රසයන්ය."),
        q("නාට්‍ය ශාස්ත්‍රයේ භරතමුනි විසින් ප්‍රථමයෙන්ම දක්වන ලද මූලික රස සංඛ්‍යාව කීයද?", "8 කි", "12 කි", "4 කි", "22 කි", "මුල් කාලයේ රස 8ක් දක්වා තිබූ අතර පසුව 9 වන රසය ලෙස ශාන්ත රසය එක් විය."),
        q("නව රසයන්ගෙන් 9 වන රසය ලෙස පසුකාලීනව එක් කරන ලද මානසික සංහිඳියාව දනවන රසය කුමක්ද?", "ශාන්ත රසය", "හාස්‍ය රසය", "රෞද්‍ර රසය", "වීර රසය", "සිතට සැනසීම හා නිරාමිස ප්‍රීතිය ගෙන දෙන භාවය ශාන්ත රසය නම් වේ."),
        q("ප්‍රේමය, ආලය සහ සුන්දරත්වය ප්‍රකාශ කරන රාග හා ගීත තුළින් ජනනය වන රසය කුමක්ද?", "ශෘංගාර රසය", "බීභත්ස රසය", "භයානක රසය", "කරුණ රසය", "යමන්, ඛමාජ් වැනි රාග සහ ප්‍රේම ගීත තුළින් ප්‍රධානව ශෘංගාර රසය මතුවේ."),
        q("දුක, ශෝකය හා වියෝගය දනවන රාග හා ගීතවලදී ප්‍රකට වන ප්‍රධාන රසය කුමක්ද?", "කරුණ රසය", "වීර රසය", "හාස්‍ය රසය", "අද්භුත රසය", "පූරියා ධනශ්‍රී, භෛරවී හා මාරවා වැනි රාග බොහෝ විට කරුණ රසය මවයි."),
        q("උද්යෝගය, නිර්භීතකම සහ රණකාමී ජවය ඉස්මතු වන ගීත හා වාදනවලින් ප්‍රකාශ වන රසය කුමක්ද?", "වීර රසය", "ශාන්ත රසය", "කරුණ රසය", "ශෘංගාර රසය", "දේශාභිමානී ගීත සහ භිම්පලාසි, කෙදාර් හෝ මල්හාර් ඇසුරෙන් වීර රසය නැංවිය හැකිය."),
        q("කෝපය හා ආවේගශීලීත්වය ප්‍රකාශ කරන රංග හා සංගීත අවස්ථාවලදී ප්‍රමුඛ වන රසය කුමක්ද?", "රෞද්‍ර රසය", "හාස්‍ය රසය", "ශාන්ත රසය", "ශෘංගාර රසය", "වේගවත් තීව්‍ර හඬ සහ ආවේගශීලී චලන මගින් රෞද්‍ර රසය මතු කෙරේ."),
        q("පිළිකුල හෝ අප්‍රසන්න බව නිරූපණය වන නාට්‍ය අවස්ථාවලදී මතුවන රසය කුමක්ද?", "බීභත්ස රසය", "ශෘංගාර රසය", "අද්භුත රසය", "ශාන්ත රසය", "අප්‍රසන්න හෝ ජුගුප්සාජනක දසුනකින් හෝ පසුබිමකින් බීභත්ස රසය ජනනය වේ."),
        q("විස්මය හා ආශ්චර්යය ප්‍රකාශ කරන සංගීතමය හා නාට්‍යමය අවස්ථාවලදී ඇතිවන රසය කුමක්ද?", "අද්භුත රසය", "කරුණ රසය", "හාස්‍ය රසය", "භයානක රසය", "පුදුමය දනවන නාද රටා හා සිදුවීම් තුළින් අද්භුත රසය උපදී."),
        q("තැතිගැන්ම හා බිය උපදවන චිත්‍රපට හෝ නාට්‍ය පසුබිම් සංගීතයෙන් මැවෙන්නේ කුමන රසයද?", "භයානක රසය", "ශාන්ත රසය", "හාස්‍ය රසය", "ශෘංගාර රසය", "අඳුරු හා අසමතුලිත නාද රටා යොදාගෙන නරඹන්නා තුළ භයානක රසය මතු කරයි."),
        q("රාගයක් ගායනා කිරීමේදී මෙන්ම සාමාන්‍ය ගීත ගායනයේදී හඬ පුහුණුව සඳහා උදෑසන කළ යුතු හොඳම අභ්‍යාසය කුමක්ද?", "මන්ද්‍ර ෂඩ්ජයේ හා ඛරජ් ස්වරවල දිගු ආකාර රියාස් කිරීම", "ඉතා උස් හඬින් කෑගැසීම", "අයිස් වතුර පානය කිරීම", "හුස්ම හිරකරගෙන ගායනා කිරීම", "උදෑසන මන්ද්‍ර ස්වර (ඛරජ්) පුහුණුවෙන් කටහඬ ගැඹුරු, ස්ථිර හා පුළුල් වේ."),
        q("ගායනයේදී හඬ උපදවන ප්‍රධාන ජීව විද්‍යාත්මක අවයවය වන 'ස්වර තන්තු' (Vocal Cords) පිහිටා ඇත්තේ කොතැනද?", "උගුරේ ස්වරාලය (Larynx) තුළ", "නාසය අග", "දිව යට", "හෘදය වස්තුව තුළ", "පෙණහලුවලින් එන වාතය ස්වරාලයේ ස්වර තන්තු කම්පනය කිරීමෙන් මිනිස් කටහඬ උපදී."),
        q("හොඳ ගායකයෙකුගේ හුස්ම පාලනය දියුණු කිරීමට හා දිගු ස්වර ඛණ්ඩ රඳවා ගැනීමට උපකාරී වන අභ්‍යාසය කුමක්ද?", "ප්‍රාණායාම හෙවත් ශ්වසන අභ්‍යාස", "වේගයෙන් දිවීම පමණක්", "කතා නොකර නිදාගැනීම", "බර ඉසිලීම", "ප්‍රාචීරය (Diaphragm) පාලනය කරමින් ගැඹුරු හුස්ම ගැනීම හා පිටකිරීම ගායනයට අත්‍යවශ්‍ය වේ."),
        q("ගායනා කරන විට නිවැරදි ශරීර ඉරියව්ව (Posture) ලෙස සලකන්නේ කුමක්ද?", "කොඳු ඇට පෙළ සෘජුව තබා උරහිස් සැහැල්ලුවෙන් හිඳීම හෝ සිටීම", "හිස පහළට නමා උගුර තද කර ගැනීම", "පපුව වකුටු කර ඉදිරියට නැමීම", "දණහිස් උඩ නිකට තබා ගැනීම", "සෘජු ඉරියව්ව නිසා පෙණහලු සම්පූර්ණයෙන් ප්‍රසාරණය වී හුස්ම ප්‍රවාහය බාධාවකින් තොරව ගලා යයි."),
        q("කටහඬ ආරක්ෂා කර ගැනීමට ගායන ශිල්පියෙකු වැළකී සිටිය යුතු පුරුද්දක් වන්නේ කුමක්ද?", "අධික සීතල, තෙල් සහිත ආහාර හා අනවශ්‍ය කෑගැසීම්", "පිරිසිදු මඳ උණුසුම් ජලය පානය කිරීම", "නිතිපතා ස්වර අභ්‍යාස කිරීම", "ප්‍රමාණවත් නින්දක් ලබාගැනීම", "අධික සීතල පාන හා උගුර වෙහෙසවන කෑගැසීම් ස්වර තන්තුවලට හානි කරයි."),
        q("ගායනා කිරීමේදී 'නාසික හඬින්' (Nasal Tone) ගැයීම වැළැක්වීමට කළ යුත්තේ කුමක්ද?", "මුඛ කුහරය හා මෘදු තල්ල නිසි පරිදි විවෘත කර ගැයීම", "තොල් තදින් වසාගෙන ගැයීම", "දත් පූට්ටු කරගෙන ගැයීම", "නාසය අතින් වසාගෙන ගැයීම", "පැහැදිලි විවෘත හඬක් සඳහා මුඛය හා උගුර නිදහස්ව විවෘතව තබාගත යුතුය."),
        q("ශාස්ත්‍රීය හා සරල ගී ගායනයේදී 'වචන උච්චාරණය' (Diction) පැහැදිලි වීම වැදගත් වන්නේ ඇයි?", "ගීතයේ අර්ථය හා භාවය ශ්‍රාවකයාට නිවැරදිව සන්නිවේදනය වීමට", "හඬ තද කිරීමට පමණක්", "තාලය වෙනස් කිරීමට", "මයික්‍රොෆෝනය ආරක්ෂා කිරීමට", "මහාප්‍රාණ, අල්පප්‍රාණ හා වචන පැහැදිලිව උච්චාරණය කිරීමෙන් ගීතයේ රසය සම්පූර්ණ වේ."),
        q("ගායනයේදී 'සෘති සමබරතාව' හෙවත් 'බේසුර් නොවී' (In-tune) ගැයීම යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "තම්බුරාවේ හෝ පසුබිම් සංගීතයේ ස්වර ස්ථාන සමඟ නිවැරදිව සමපාත වීම", "හඬ ඉතා විශාල කර ගැයීම", "වේගයෙන් වචන ගැයීම", "තාලය අමතක කර ගැයීම", "සෑම ස්වරයකම සංඛ්‍යාතය නිවැරදි ස්ථානයේ පිහිටුවා ගායනය කිරීම ඉතා වැදගත් වේ."),
        q("කටහඬක ස්වාභාවික භේද අනුව බටහිර හා පෙරදිග සංගීතයේ කාන්තා උච්ච හඬ සහ පිරිමි ගැඹුරු හඬ හඳුන්වන්නේ කෙසේද?", "සොප්‍රානෝ (Soprano) සහ බේස් (Bass)", "ඇල්ටෝ සහ සොප්‍රානෝ", "ටෙනර් සහ ඇල්ටෝ", "මෙසෝ සහ බැරිටෝන් පමණක්", "උච්ච කාන්තා හඬ Soprano ද, පහළ ගැඹුරු පිරිමි හඬ Bass ද ලෙස වර්ග කෙරේ."),
        q("ගායන ක්ෂේත්‍රයේ 'සමූහ ගායනයකදී' (Choir / Chorus) වඩාත්ම වැදගත් වන ගුණාංගය කුමක්ද?", "සියලු දෙනාගේ හඬ, තාලය හා ස්වර ඒකාග්‍රතාවයෙන් එක්වීම", "එක් අයෙකු පමණක් අන් අය පරදා කෑගැසීම", "වෙන වෙනම තමන් කැමති ස්වරයෙන් ගැයීම", "එකම වචනය වෙනස් වේලාවට කීම", "සාමූහික ශ්‍රැති එකඟතාව හා එකම රිද්මය සමූහ ගායනයක සාර්ථකත්වයයි."),
        q("ශ්‍රව්‍ය විද්‍යාවට (Acoustics) අනුව ශබ්දය ගමන් කිරීම සඳහා අත්‍යවශ්‍ය වන්නේ කුමක්ද?", "වාතය, ද්‍රව හෝ ඝන මාධ්‍යයක්", "සම්පූර්ණ රික්තයක් (Vacuum)", "විදුලි බලය පමණක්", "අන්ධකාර පරිසරයක්", "ශබ්ද තරංග යාන්ත්‍රික තරංග බැවින් ගමන් කිරීමට මාධ්‍යයක් අවශ්‍ය වන අතර රික්තයක ගමන් නොකරයි."),
        q("වස්තුවක් තත්පරයකදී සිදු කරන කම්පන වාර ගණන (සංඛ්‍යාතය / Frequency) මනිනු ලබන සම්මත ඒකකය කුමක්ද?", "හර්ට්ස් (Hz)", "ඩෙසිබල් (dB)", "මීටර් (m)", "වොට් (W)", "සංඛ්‍යාතය Hertz ඒකකයෙන් මනිනු ලබන අතර ස්වරයේ උස් පහළ බව (Pitch) ඉන් තීරණය වේ."),
        q("ශබ්දයක 'තාරතාව' (Pitch) රඳා පවතින්නේ කුමන භෞතික රාශිය මතද?", "ශබ්ද තරංගයේ සංඛ්‍යාතය (Frequency) මත", "ශබ්දයේ වර්ණය මත", "ශාලාවේ බිත්ති ප්‍රමාණය මත", "වාදකයාගේ වයස මත", "සංඛ්‍යාතය වැඩි වන විට ස්වරය උස් (තාර) වන අතර අඩු වන විට පහළ (මන්ද්‍ර) වේ."),
        q("සංගීතයේදී මධ්‍ය සප්තකයේ ෂඩ්ජයට (Sa) වඩා තාර සප්තකයේ ෂඩ්ජයේ සංඛ්‍යාතය කෙබඳු වේද?", "හරියටම දෙගුණයකි (2:1 අනුපාතය)", "සමාන වේ (1:1 අනුපාතය)", "තුන් ගුණයකි (3:1 අනුපාතය)", "අඩකි (1:2 අනුපාතය)", "මධ්‍ය ස = 240 Hz නම්, තාර ස = 480 Hz හෙවත් දෙගුණයක් වේ."),
        q("මධ්‍ය සප්තකයේ ෂඩ්ජයේ (ස) සංඛ්‍යාතය 240 Hz යැයි ගතහොත් මන්ද්‍ර ෂඩ්ජයේ සංඛ්‍යාතය කොපමණ වේද?", "120 Hz", "480 Hz", "360 Hz", "720 Hz", "මන්ද්‍ර සප්තකයේ ස්වරයක සංඛ්‍යාතය මධ්‍ය සප්තකයේ එම ස්වරයේ සංඛ්‍යාතයෙන් අඩකි."),
        q("ශබ්දයේ 'ප්‍රබලතාව හෙවත් හඬේ විශාලත්වය' (Loudness) මනිනු ලබන සම්මත ඒකකය කුමක්ද?", "ඩෙසිබල් (dB)", "හර්ට්ස් (Hz)", "කිලෝග්‍රෑම් (kg)", "තත්පර (s)", "ශබ්ද තීව්‍රතා මට්ටම ඩෙසිබල් ඒකකයෙන් මනින අතර අධික dB කනට හානිකර වේ."),
        q("වස්තුවක කම්පන 'විස්තාරය' (Amplitude) වැඩි වන විට ශබ්දයෙහි ඇතිවන වෙනස කුමක්ද?", "ශබ්දයේ හඬ විශාල වීම (ප්‍රබලතාව වැඩිවීම)", "ස්වරය ඉහළ නැගීම", "ශබ්දය සම්පූර්ණයෙන් නැති වීම", "භාණ්ඩයේ වර්ණය වෙනස් වීම", "වීණා තන්තුවක් තදින් ඇද්ද විට විස්තාරය වැඩි වී හඬ වැඩිපුර ඇසේ."),
        q("මිනිස් කනට ඇසෙන සාමාන්‍ය ශ්‍රව්‍ය පරාසය (Audible Range) කොපමණද?", "20 Hz සිට 20,000 Hz දක්වා", "1 Hz සිට 100 Hz දක්වා", "50,000 Hz ට ඉහළ", "0 Hz සිට 10 Hz දක්වා", "20 Hz ට අඩු හා 20 kHz ට වැඩි ශබ්ද සාමාන්‍ය මිනිස් කනට නොඇසේ."),
        q("තන්තුවකින් නිකුත් වන ස්වරයේ සංඛ්‍යාතය (Pitch) වැඩි කිරීම සඳහා තන්තුවේ දිගට කළ යුත්තේ කුමක්ද?", "කම්පනය වන දිග කෙටි කිරීම (තද කර ඇල්ලීම)", "දිග දෙගුණයකින් වැඩි කිරීම", "තන්තුව බුරුල් කිරීම", "තන්තුව ගණකම් කිරීම", "සිතාරයේ හෝ ගිටාරයේ ඉහළ පර්දා වෙත යන විට කම්පන දිග කෙටි වී උස් ස්වර ඇසේ."),
        q("සංගීත ශාලාවක අනවශ්‍ය 'දෝංකාරය' (Reverberation/Echo) අඩු කිරීම සඳහා යොදාගන්නා උපක්‍රමය කුමක්ද?", "බිත්තිවල ධ්වනි අවශෝෂක රෙදි, කාපට් හා පැනල් සවි කිරීම", "බිත්ති සියල්ල වීදුරු හා ටයිල් වලින් ආවරණය කිරීම", "ජනෙල් සියල්ල තදින් වැසීම", "ශබ්ද විකාශන යන්ත්‍ර උපරිමයෙන් වැඩි කිරීම", "මෘදු පෘෂ්ඨ මගින් ශබ්ද තරංග පරාවර්තනය අඩු කර පැහැදිලි ශ්‍රවණ තත්ත්වයක් ඇති කරයි."),
        q("සංගීත ප්‍රසංගයකදී 'මයික්‍රොෆෝනයක්' (Microphone) මගින් සිදු කරන මූලික කාර්යය කුමක්ද?", "ශබ්ද තරංග විද්‍යුත් සංඥා බවට පරිවර්තනය කිරීම", "විද්‍යුත් සංඥා ආලෝකය බවට හැරවීම", "ස්වර වෙනස් කිරීම", "තාලය ගණන් කිරීම", "ගායකයාගේ හඬ විද්‍යුත් ධාරාවක් බවට හරවා වර්ධකය වෙත යවන්නේ මයික්‍රොෆෝනයයි."),
        q("පටිගත කිරීමේ මැදිරියක හෝ වේදිකාවක ඇතිවන කර්කශ 'ෆීඩ්බැක්' (Feedback / කීං ගෑම) නැවැත්වීමට කළ යුත්තේ කුමක්ද?", "මයික්‍රොෆෝනය ස්පීකර් ඉදිරිපසට කෙළින් යොමු නොකිරීම", "සියලු ස්පීකර් හඬ උපරිම කිරීම", "මයික්‍රොෆෝනය ස්පීකරයට තබා තද කිරීම", "තම්බුරාව නිවා දැමීම", "ස්පීකරයෙන් එන ශබ්දය නැවත මයික්‍රොෆෝනයට ඇතුළු වීම වැළැක්වීමෙන් ෆීඩ්බැක් නතර කළ හැකිය."),
        q("ප්‍රායෝගික සංගීත පරීක්ෂණයකදී පළමුවෙන්ම ශිෂ්‍යයෙකු තම 'මූලික ස්වරය' (Scale / ශ්‍රැතිය) තෝරා ගත යුත්තේ කෙසේද?", "තම කටහඬට පහසුවෙන් සප්තකය පුරා ගැයිය හැකි ස්වරය අනුව", "අනෙක් අය තෝරන ස්වරයම බලහත්කාරයෙන් ගැනීමෙන්", "වැඩිම උස් ස්වරයෙන් පටන් ගැනීමෙන්", "පරීක්ෂකවරයාට අපහසු ස්වරයකින්", "සාමාන්‍යයෙන් C, C# හෝ G# වැනි තමන්ට ස්වාභාවිකව ගැළපෙන පරිමාණය තෝරාගත යුතුය."),
        q("O/L ප්‍රායෝගික පරීක්ෂණයේදී රාගයක් ගායනා කිරීමට පෙර ශිෂ්‍යයා අනිවාර්යයෙන්ම ඉදිරිපත් කළ යුතු මූලික අංග මොනවාද?", "ආරෝහණ, අවරෝහණ සහ පකඩ්", "රාගයේ උපන් වර්ෂය පමණක්", "වේගවත් තාන පමණක්", "බටහිර ස්වර පුවරුව", "රාගයේ හැඩය පෙන්වීමට ආරෝහණ, අවරෝහණ හා මූලික පකඩ් ස්වර ඛණ්ඩය ගැයිය යුතුය."),
        q("ප්‍රායෝගික විභාගයේදී 'තාල තැබීම' (අතින් තාල දැමීම) සිදු කරන විට නිවැරදි සම්මත ක්‍රමය කුමක්ද?", "තාලි සඳහා අත්පොළසන්ද ඛාලි සඳහා අත විවෘත කිරීමද", "කකුලෙන් බිමට ගසමින් රිද්මය තැබීම", "හිස දෙපසට වැනීමෙන් පමණක් පෙන්වීම", "මේසය මත පෑනකින් තට්ටු කර ගැනීම", "අතින් තාල තැබීමේදී තාලි, ඛාලි සහ මාත්‍රා ඇඟිලිවලින් පැහැදිලිව ගණන් කළ යුතුය."),
        q("ත්‍රිතාලය අතින් තාල තබා පෙන්වීමේදී 9 වන මාත්‍රාව වන 'ඛාලි' ස්ථානය පෙන්විය යුත්තේ කෙසේද?", "දකුණු අත වම් අත්ලෙන් ඉවතට විවෘත කර හිස් අත පෙන්වීමෙන්", "තදින් අත්පොළසන් ගැසීමෙන්", "ඇඟිලි මිට මොළවා ගැනීමෙන්", "නැගිට සිටීමෙන්", "ඛාලි යනු ශබ්ද රහිත තැන බැවින් අත්ල උඩු අතට හරවා පසෙකට විවෘත කර පෙන්වයි."),
        q("ප්‍රායෝගික පරීක්ෂණයේදී 'කර්ණ පුහුණු' (Ear Training / ස්වර හඳුනාගැනීම) අංගයෙන් පරීක්ෂා කරනු ලබන්නේ කුමක්ද?", "වාදනය කරන හෝ ගයන ස්වර සහ තාල සවනින් හඳුනාගැනීමේ හැකියාව", "ඇස් පෙනීමේ තියුණු බව", "වේගයෙන් ලිවීමේ හැකියාව", "භාණ්ඩයක බර දැනගැනීම", "ගුරුවරයා වයන ස්වර ඛණ්ඩ කනෙන් අසා නිවැරදිව නම් කිරීමට හෝ ගැයීමට සිසුවාට හැකි විය යුතුය."),
        q("කර්ණ පුහුණුවේදී ශුද්ධ ස්වර හා කෝමල ස්වර වෙන්කර හඳුනාගැනීම දියුණු කරගැනීමට හොඳම ක්‍රමය කුමක්ද?", "නිවැරදිව සුසර කළ හාමෝනියම් හෝ තම්බුරාව සමඟ ස්වර සංසන්දනය කරමින් ගැයීම", "පොතක ලියා ඇති ආකාරය කටපාඩම් කිරීම පමණක්", "ශබ්දයකින් තොරව නිහඬව කල්පනා කිරීම", "වෙනස් නොවන එක් ස්වරයක් පමණක් ඇසීම", "ෂඩ්ජයට සාපේක්ෂව එක් එක් ස්වරයේ නාද ස්ථානය නැවත නැවත අසා ගැයීමෙන් කන පුහුණු වේ."),
        q("ප්‍රායෝගික විභාගයේ Viva (වාචික ප්‍රශ්න) අවස්ථාවේදී ශිෂ්‍යයෙකු අනුගමනය කළ යුතු නිවැරදි ආචාරශීලී පිළිවෙත කුමක්ද?", "විනීතව සවන් දී පැහැදිලිව හා සංක්ෂිප්තව නිවැරදි පිළිතුරු දීම", "පරීක්ෂකවරයාගේ කතාව මැදින් බාධා කිරීම", "නොදන්නා කරුණු බොරුවට ගොතා පැවසීම", "පිළිතුරු නොදී ඉවත බලා සිටීම", "නිහතමානීව සවන් දී න්‍යායාත්මක හා ප්‍රායෝගික දැනුම විශ්වාසයෙන් ඉදිරිපත් කළ යුතුය."),
        q("සිසුන් බොහෝ විට ප්‍රායෝගික පරීක්ෂණයේදී රාගයක් ගයන විට සිදු කරන සුලභ වරදක් වන්නේ කුමක්ද?", "අත්වැරදීමෙන් වර්ජිත ස්වර ගැයීම හෝ තාලයේ ලය වේගවත් කිරීම", "මුලින්ම ආරෝහණ ගැයීම", "තම්බුරාව සුසර කර ගැනීම", "සම මත නිවැරදිව පැමිණීම", "නොඉවසිලිමත්කම නිසා ලය වෙනස් වීම හා රාගයේ සීමා පැනීම සුලභ අඩුපාඩු වේ."),
        q("ප්‍රායෝගික පරීක්ෂණයකට සූදානම් වන වාද්‍ය ශිල්පියෙකු පරීක්ෂණ ශාලාවට ඇතුළු වීමට පෙර කළ යුතු ප්‍රධාන දෙය කුමක්ද?", "භාණ්ඩය නිවැරදිව සුසර කර ගැනීම", "භාණ්ඩය ගලවා කොටස් වෙන් කිරීම", "තන්තු බුරුල් කර තැබීම", "වතුරෙන් සම තෙත් කිරීම", "විභාග ශාලාවේ කාලය නාස්ති නොවන සේ පිටතදී භාණ්ඩය නිවැරදිව සුසර කරගෙන සිටිය යුතුය."),
        q("ජන ගීයක් ප්‍රායෝගික පරීක්ෂණයකදී ඉදිරිපත් කරන විට වඩාත්ම වැදගත් වන්නේ කුමක්ද?", "එම ජන ගීයට ආවේණික ගැමි උච්චාරණය, හඬ හැසිරවීම හා රිද්මය රැකීම", "බටහිර ඔපෙරා හඬින් ගැයීම", "ඉංග්‍රීසි වචන එකතු කිරීම", "සංකීර්ණ හින්දුස්ථානි තාන යෙදීම", "පැල් කවියක් හෝ ගොයම් කවියක් එහි ස්වාභාවික ගැමි ආර රැකෙන සේ ගැයිය යුතුය."),
        q("ගීතයක් ගායනා කිරීමේදී 'භාව ප්‍රකාශනය' (Expression) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "ගීතයේ අර්ථයට අනුකූල හැඟීම් හඬින් හා මුහුණෙන් ප්‍රකාශ කිරීම", "හඬ උපරිමයෙන් වැඩි කර කෑගැසීම", "මුහුණ තද කරගෙන සිටීම", "වේගයෙන් ඇස් පිල්ලම් ගැසීම", "පදවල අරුත අනුව සතුට, දුක හෝ භක්තිය හඬෙහි මෘදු තද භාවයෙන් දැනවීමයි."),
        q("සංගීතයේදී 'සංයුක්ත ගතික ලකුණු' (Dynamics) අතරින් මෘදුව හා හඬ නගා ගැයීමට යොදන බටහිර සංකේත මොනවාද?", "Piano (p) සහ Forte (f)", "Allegro සහ Adagio", "Sharp සහ Flat", "Treble සහ Bass", "සංගීතයේදී 'p' මෘදු හඬත් 'f' ප්‍රබල හඬත් නියෝජනය කරන ගතික ලකුණු වේ."),
        q("ප්‍රාථමික හෝ O/L සිසුවෙකු නිර්මාණාත්මක ගී තනුවක් (Creative Melody) සකස් කිරීමේදී මුලින්ම සැලකිලිමත් විය යුත්තේ කුමක් ගැනද?", "පදමාලාවේ අර්ථය, රසය හා වෘත්ත රිද්මය", "විශාලම වාද්‍ය භාණ්ඩය මිලදී ගැනීම", "ප්‍රසංග ශාලාවේ ටිකට් ගාස්තුව", "වචන කපා දැමීම", "කාව්‍යමය පදවල රිද්මය හා හැඟීම හඳුනාගෙන ඊට සුදුසු රාග හෝ ස්වර රටා යෙදිය යුතුය."),
        q("සරල ගීයක් නිර්මාණය කිරීමේදී 'ස්ථායි' සහ 'අන්තරා' කොටස් අතර පැවතිය යුතු සම්බන්ධතාව කුමක්ද?", "තාලය හා මූලික භාවය රැකගනිමින් අන්තරාව උච්ච ස්වර වෙත යාම", "අන්තරාව සම්පූර්ණයෙන් වෙනස් තාලයකින් ගැයීම", "ස්ථායි කොටස අවසානයේ නැවත නොගැයීම", "අන්තරාව කතා කර පෙන්වීම", "ස්ථායි කොටසේ මධ්‍ය ස්වරවලින් පසු අන්තරාව තාර ස්වර කරා විහිදී නැවත ස්ථායියට පැමිණේ."),
        q("සරල ගීයක් ආරම්භයේදී ගායනයට පෙර වාදනය කරන හඳුන්වාදීමේ සංගීත කොටස හඳුන්වන්නේ කුමන නමින්ද?", "පෙර වාදනය (Prelude / Intro)", "අතුරු වාදනය (Interlude)", "පසු වාදනය (Outro)", "සර්ගම් කොටස", "ගීතයේ රසය හා ස්වර-තාල පසුබිම ශ්‍රාවකයාට හඳුන්වා දෙන මුල් වාදනය Prelude වේ."),
        q("ගීතයක ස්ථායි කොටස සහ අන්තරා කොටස අතරතුර වාදනය කරනු ලබන සංගීත ඛණ්ඩය කුමක්ද?", "අතුරු වාදනය (Interlude)", "පෙර වාදනය (Prelude)", "අවසන් වාදනය (Coda)", "ඛරජ් අභ්‍යාසය", "ප්‍රධාන ගායන කොටස් අතර සම්බන්ධය හා රසය රඳවන වාද්‍ය ඛණ්ඩය අතුරු වාදනයයි."),
        q("කණ්ඩායම් වශයෙන් වාදනය කරන 'සමූහ වාද්‍ය ඛණ්ඩයක්' (Ensemble) සාර්ථක වීමට අත්‍යවශ්‍යම පූර්ව කොන්දේසිය කුමක්ද?", "සියලු භාණ්ඩ එකම ශ්‍රැතියට (Pitch) සුසර කර තිබීම", "එක් එක් භාණ්ඩය වෙනස් ශ්‍රැතිවල තිබීම", "කාලසටහනකින් තොරව වාදනය කිරීම", "හැමෝම එකිනෙකා නොබලා වැයීම", "ශ්‍රැති නොගැළපුණහොත් සමූහ වාදනයේ මිහිරියාව බිඳී කර්කශ බවක් ඇති වේ."),
        q("දේශීය හා පෙරදිග සංගීතයේදී 'පරීක්ෂණාත්මක නිර්මාණ' (Experimental Music) බිහි කිරීමෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "සාම්ප්‍රදායික ශිල්පය මත පිහිටා නව නාද රටා ගවේෂණය කිරීම", "පැරණි සියලු දැනුම අමතක කර දැමීම", "සංගීතය සම්පූර්ණයෙන් නිහඬ කිරීම", "එකම ගීතය නැවත නැවත පිටපත් කිරීම", "පැරණි රාග හා ජන නාද නව වාද්‍ය සංකලන සමඟ මුසු කර නව නිර්මාණ බිහි කෙරේ."),
        q("පෙරදිග සංගීතය හා බටහිර සංගීතය සංසන්දනය කිරීමේදී පෙරදිග සංගීතයේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "රාග, මීන්ඩ්, ගමක හා ඒකස්වර මධුරත්වය (Melody) ප්‍රමුඛ වීම", "එකවර ස්වර සමූහ (Harmony) පමණක් යෙදීම", "ශ්‍රැති 22 භාවිත නොකිරීම", "සෑම විටම පියානෝව භාවිත කිරීම", "පෙරදිග සංගීතය ස්වර එකින් එක අලංකාරව ගලා යන Melody මූලික ක්‍රමය අනුගමනය කරයි."),
        q("බටහිර සංගීතයේ මූලික ශිල්පීය ලක්ෂණය ලෙස හඳුන්වනු ලබන්නේ කුමක්ද?", "සංධ්වනි හෙවත් Harmony සහ Polyphony භාවිතය", "රාග ගායනය හා තම්බුරාව", "ශ්‍රැති 22න් ගී ගැයීම", "තබ්ලාවෙන් තේකා වැයීම", "එකවර ස්වර කිහිපයක් නාද කරමින් කෝඩ්ස් (Chords) හා හාමනි ගොඩනැගීම බටහිර සංගීතයේ විශේෂත්වයයි."),
        q("බටහිර සංගීතයේ සප්ත ස්වර පද්ධතිය වන 'Do, Re, Mi, Fa, Sol, La, Ti' හා සමාන වන පෙරදිග ස්වර මොනවාද?", "ස, රි, ග, ම, ප, ධ, නි", "ක, ඛ, ග, ඝ, ච, ඡ, ජ", "ත, ද, න, ප, බ, ම, ය", "අ, ආ, ඉ, ඊ, උ, ඌ, එ", "බටහිර සොල්ෆා (Solfa) ස්වර හත පෙරදිග සප්ත ස්වර හතට අනුරූප වේ."),
        q("බටහිර ස්ටාෆ් ස්වර ප්‍රස්තාරයේ (Staff Notation) සමාන්තර රේඛා කීයක් පිහිටා තිබේද?", "5 කි", "7 කි", "3 කි", "12 කි", "තිරස් රේඛා 5ක් සහ ඒ අතර පිහිටි අවකාශ 4ක් මත බටහිර ස්වර ලියනු ලැබේ."),
        q("බටහිර සංගීතයේදී 'C Major' පරිමාණය හා පෙරදිග සංගීතයේ සමාන ස්වර පිහිටීමක් ඇති ථාටය කුමක්ද?", "බිලාවල් ථාටය (සියලු ශුද්ධ ස්වර)", "භෛරවී ථාටය", "තෝඩි ථාටය", "මාර්වා ථාටය", "C Major පරිමාණයේ සියලු ස්වර ස්වාභාවික වන අතර එය බිලාවල් ථාටයේ ශුද්ධ ස්වරවලට සමාන වේ."),
        q("බටහිර සංගීතයේදී භාවිත කරන 'Sharp (#)' ලකුණෙන් ස්වරයකට සිදුවන වෙනස කුමක්ද?", "ස්වරය අර්ධ ස්වරයකින් (Semitone) ඉහළ නැංවීම", "ස්වරය අර්ධ ස්වරයකින් පහළ දැමීම", "ස්වරය සම්පූර්ණයෙන් නිහඬ කිරීම", "ස්වරයේ කාලය දෙගුණ කිරීම", "Sharp (#) ලකුණ පෙරදිග 'තීව්‍ර' වීමට සමානව ස්වරය අඩ පියවරකින් උස් කරයි."),
        q("බටහිර සංගීතයේදී 'Flat (b)' ලකුණෙන් ස්වරයකට සිදුවන බලපෑම කුමක්ද?", "ස්වරය අර්ධ ස්වරයකින් (Semitone) පහළ දැමීම", "ස්වරය අර්ධ ස්වරයකින් ඉහළ දැමීම", "ස්වරය දෙගුණයක් දිගු කිරීම", "ස්වරය නැවත වැයීම", "Flat (b) සංකේතය පෙරදිග 'කෝමල' ස්වර මෙන් ස්වරය අඩ පියවරකින් පහත් කරයි."),
        q("සෞන්දර්ය රසවින්දනය යනු කුමක්දැයි ඉතා සරලව හඳුන්වා දිය හැක්කේ කෙසේද?", "කලා නිර්මාණයක සුන්දරත්වය, භාවය හා ශිල්පීය අගය බුද්ධිමත්ව විඳගැනීම", "හුදෙක් ඝෝෂාකාරී හඬට අත්පොළසන් දීම", "වාද්‍ය භාණ්ඩවල මිල ගණන් සෙවීම", "වරදක් සෙවීම සඳහා පමණක් ඇහුම්කන් දීම", "සංගීතයේ ස්වර, තාල, අර්ථය සහ නිර්මාණශීලීත්වය භාවාත්මකව අගය කිරීම රසවින්දනයයි."),
        q("හොඳ සංගීත රසිකයෙකු (විදග්ධ ශ්‍රාවකයෙකු) ප්‍රසංග ශාලාවකදී හැසිරිය යුත්තේ කෙසේද?", "ශිල්පීන්ට ගරු කරමින් නිහඬව සවන් දී අදාළ තැනදී අගය කිරීම", "ප්‍රසංගය මැද ශබ්ද නගා දුරකථනයෙන් කතා කිරීම", "නිර්මාණය අවසන් වීමට පෙර බාධා කිරීම", "අනෙක් අයට බාධා වන සේ නැගිට ඇවිදීම", "ශාස්ත්‍රීය හෝ සරල ප්‍රසංගයක ශිල්පියාගේ මානසික ඒකාග්‍රතාව රැකීම ප්‍රේක්ෂක යුතුකමකි."),
        q("වර්තමාන සමාජයේ වෛද්‍ය විද්‍යාත්මකව පවා භාවිත කෙරෙන 'සංගීත චිකිත්සාව' (Music Therapy) මගින් සිදු වන්නේ කුමක්ද?", "මානසික ආතතිය අඩු කර කායික හා මානසික සුවය සැලසීම", "ශබ්දය මගින් කන් බිහිරි කිරීම", "නින්ද සම්පූර්ණයෙන් නැති කිරීම", "ඖෂධ නිෂ්පාදනය කිරීම", "සුමිහිරි රාග හා සංගීත නාද මගින් ස්නායු පද්ධතිය සන්සුන් කර ප්‍රතිකාර සඳහා සහාය වේ."),
        q("දරුවන් නැළවීමේ සිට වැඩිහිටියන්ගේ මානසික සුවය දක්වා සංගීතය බලපෑම් කරන්නේ කවර හේතුවක් නිසාද?", "මිනිස් මොළයේ භාවාත්මක හා ස්නායු පද්ධතිය සමඟ සෘජුව සම්බන්ධ වන නිසා", "ශරීරයේ අස්ථි සංඛ්‍යාව වැඩි කරන නිසා", "ආහාර ජීර්ණය නතර කරන නිසා", "හුදෙක් කාලය නාස්ති කරන නිසා", "රිද්මය හා මධුර ස්වර මනසේ ධනාත්මක හෝමෝන ස්‍රාවය උත්තේජනය කරයි."),
        q("සංගීත අධ්‍යාපනය තුළ 'ස්වර ලිපි කියවීමේ' (Sight Singing / Sight Reading) හැකියාවෙන් ලැබෙන ප්‍රයෝජනය කුමක්ද?", "නොදන්නා ගීතයක් හෝ වාදනයක් ප්‍රස්තාරය බලා ක්ෂණිකව ගැයීමට හෝ වැයීමට හැකිවීම", "පොත් මුද්‍රණය කිරීමට පමණක්", "කටපාඩම් කිරීම අනවශ්‍ය නොවී අමතක කිරීමට", "භාණ්ඩය අලුත්වැඩියා කිරීමට", "ස්වර ප්‍රස්තාර කියවීමේ හැකියාව සංගීතඥයෙකුගේ සාක්ෂරතාව ලෙස සැලකේ."),
        q("ශාස්ත්‍රීය සංගීත ප්‍රසංගයකදී ගායකයා සහ තබ්ලා වාදකයා අතර අදහස් හුවමාරුව සිදුවන්නේ කෙසේද?", "ඇස් බැල්ම, හිස චලනය හා 'සම' මත ලය පාලනයෙන්", "මයික්‍රොෆෝනයෙන් නවතා කතා කිරීමෙන්", "පේළි පිටින් ලිපි ලියා යැවීමෙන්", "දුරකථන ඇමතුම් මගින්", "ප්‍රසංගය අතරතුර ශිල්පීහු සියුම් ඉඟි හා තාල සංඥා මගින් එකඟතාවයෙන් වැයීම සිදු කරති."),
        q("හින්දුස්ථානි ප්‍රායෝගික ගායනයේදී 'තාන' (Taan) ගැයීමේදී ගායකයා අනුගමනය කළ යුතු නීතිය කුමක්ද?", "රාගයේ නියමිත ස්වර පමණක් යොදා පැහැදිලිව හා තාලයට ගැයීම", "රාගයේ නැති ස්වර කලවම් කිරීම", "තාලය කැඩෙන පරිදි ගැයීම", "අක්ෂර නොපෙනෙන සේ මුමුණා ගැයීම", "වේගවත් තාන ඛණ්ඩයක වුවද එක් එක් ස්වරය පැහැදිලිව (දානේදාර්) හා රාග සීමාව තුළ තිබිය යුතුය."),
        q("ප්‍රායෝගික විභාගයේදී 'කවි හෝ ජන ගීයක්' නියමිත තාලයට තබා ගැනීමේදී මතක තබාගත යුතු කරුණ කුමක්ද?", "වචන ගණනට වඩා ඡන්දස හා ගැමි ලය නිවැරදිව රැකීම", "හින්දුස්ථානි තබ්ලා තේකාවක් ගැයීම", "ඉතා වේගයෙන් කියවා අවසන් කිරීම", "පේළි අතර විනාඩියක් නැවතීම", "ජන කවියේ නාදය හා මාත්‍රා ඡන්දස් රටාව ආරක්ෂා කිරීම වැදගත් වේ."),
        q("සංගීත කණ්ඩායමක 'නායකයා හෝ සන්නායකවරයා' (Conductor) ඉටු කරන ප්‍රධාන කාර්යය කුමක්ද?", "සියලු වාදකයන්ගේ ලය, ගතික හා ප්‍රවේශ ස්ථාන මෙහෙයවීම", "වාද්‍ය භාණ්ඩ බිම තබා ගැනීම", "ප්‍රේක්ෂකයන් ගණන් කිරීම", "ශාලාවේ විදුලි පහන් මාරු කිරීම", "වාද්‍ය වෘන්දයක සමබරතාව හා එකමුතු වාදනය සන්නායකවරයාගේ හස්ත සංඥාවලින් මෙහෙයවේ."),
        q("සංගීත නිර්මාණකරණයේදී 'ප්‍රකාශන හිමිකම' (Copyright / බුද්ධිමය දේපළ) ආරක්ෂා කිරීම වැදගත් වන්නේ ඇයි?", "නිර්මාණකරුවාගේ අයිතිය, ගෞරවය හා ආර්ථික ප්‍රතිලාභ සුරැකීමට", "ගීත ගැයීම සම්පූර්ණයෙන් තහනම් කිරීමට", "නව ගීත බිහිවීම වැළැක්වීමට", "වාද්‍ය භාණ්ඩ මිල ඉහළ දැමීමට", "තනු නිර්මාපකයන්, ගීත රචකයන් හා ගායකයන්ගේ බුද්ධිමය දේපළට නීතිමය ආරක්ෂාව තිබිය යුතුය."),
        q("වෙනත් සංගීතඥයෙකුගේ ගීත තනුවක් අවසරයකින් හා සඳහනකින් තොරව තමන්ගේ මෙන් භාවිත කිරීම හඳුන්වන්නේ කෙසේද?", "බුද්ධිමය දේපළ සොරකම (Plagiarism / කොල්ලකෑම)", "ශාස්ත්‍රීය අධ්‍යයනය", "රාග ප්‍රස්තාරය", "ගුරුකුල සම්ප්‍රදාය", "නිර්මාණාත්මක කලාවේ ආචාරධර්ම අනුව අනුන්ගේ නිර්මාණ සොරකම් කිරීම නීති විරෝධී හා සදාචාර විරෝධී වේ."),
        q("O/L විභාගයේදී 'ස්වර ප්‍රස්තාරයක්' පත්‍රයේ පිළිවෙළට ලියා දැක්වීමේදී අනිවාර්යයෙන් ඇතුළත් කළ යුතු තොරතුරු මොනවාද?", "රාගය, තාලය, සම/ඛාලි/තාලි සංකේත සහ විභාග රේඛා", "සංගීත ශාලාවේ නම පමණක්", "ශිෂ්‍යයාගේ ප්‍රියතම වර්ණය", "වාද්‍ය භාණ්ඩයේ මිල", "මාත්‍රා, විභාග ඉරි, සම (X), ඛාලි (0) හා අංක සංකේත නිවැරදිව සටහන් කළ යුතුය."),
        q("සංගීත ක්ෂේත්‍රය ඇසුරින් වර්තමානයේ පවතින නවීන වෘත්තීය අවස්ථාවක් වන්නේ කුමක්ද?", "ශබ්ද ඉංජිනේරු විද්‍යාව, සංගීත අධ්‍යක්ෂණය හා සංගීත ගුරු වෘත්තිය", "ගොඩනැගිලි ඉදිකිරීම පමණක්", "මෝටර් රථ අලුත්වැඩියාව පමණක්", "ලෝහ උණු කිරීම", "ගායනයට හා වාදනයට අමතරව ශබ්ද පටිගත කිරීම, චිත්‍රපට සංගීතය හා සංගීත චිකිත්සාව වෘත්තීන් වේ."),
        q("සංගීත ශිල්පියෙකු තම කටහඬට වෙහෙස දැනෙන අවස්ථාවක ගත යුතු සුදුසුම පියවර කුමක්ද?", "හඬට විවේකය ලබා දී මඳ උණුසුම් ජලය පානය කිරීම", "වැඩිපුර උස් ස්වරවලින් පුහුණු වීම", "අධික සීතල අයිස්ක්‍රීම් ආහාරයට ගැනීම", "කෑගසා උගුර පෑදීම", "ස්වර තන්තු ඉදිමීම හෝ තුවාල වීම වැළැක්වීමට හඬ විවේකය (Vocal Rest) අත්‍යවශ්‍ය වේ."),
        q("'ලය විචලනය' හෙවත් ගීතයක් ගයන අතරතුර නොදැනුවත්ව වේගය වැඩි වීම වළක්වා ගැනීමට ශිෂ්‍යයා කළ යුත්තේ කුමක්ද?", "තාලය සමඟ නිරන්තර අභ්‍යාස කිරීම (Metronome / තබ්ලා සමඟ)", "වේගය ගැන නොසිතා ගැයීම", "ඇස් තදින් පියා ගැනීම", "වචන කෙටි කර ගැයීම", "මෙට්‍රොනෝමයකට හෝ තබ්ලා තේකාවට අනුව පුහුණුවීමෙන් ස්ථිර ලය පවත්වා ගත හැකිය."),
        q("පෙරදිග සංගීත පන්තියක භාවිත කරන 'සාමූහික තාල තැබීමේ' ක්‍රමයෙන් සිසුන් තුළ වර්ධනය වන ගුණාංගය කුමක්ද?", "එකමුතුකම, සමාධිය හා නිරවද්‍ය කාල සංවේදනය", "එකිනෙකා සමඟ තරඟ කර කෑගැසීම", "අත්ල රිදවා ගැනීම පමණක්", "ස්වර අමතක වීම", "එකමුතු රිද්ම සංවේදනය හා අන් අයට සවන් දෙමින් වැඩ කිරීමේ හැකියාව දියුණු වේ."),
        q("රාග ගායනයේදී 'මුර්කි' (Murki) සහ 'ඛට්කා' (Khatka) වැනි කුඩා ස්වර අලංකාර භාවිතයෙන් ලැබෙන විශේෂත්වය කුමක්ද?", "ගායනයට සියුම් අලංකාරයක් හා කලාත්මක බවක් එක්වීම", "තාලය සම්පූර්ණයෙන් කැඩී යාම", "රාගය වෙනස් වී යාම", "හඬ රළු බවට පත්වීම", "ඉක්මන් කෙටි ස්වර පොකුරු මගින් ගායනය රසවත් හා ජීවමාන බවට පත් කෙරේ."),
        q("සිංහල ගීතයක අර්ථ රසය වඩාත් ඉස්මතු වීම සඳහා තනු නිර්මාණයේදී සලකන ප්‍රධාන සාධකයක් කුමක්ද?", "අදාළ හැඟීමට ගැළපෙන රාග හා ස්වර සංයෝජන තෝරාගැනීම", "හැම ගීතයටම එකම තනුව දැමීම", "ඉංග්‍රීසි තාල පමණක් ගැනීම", "වචනවල තේරුම නොබැලීම", "ශෝක ගීයකට කරුණ රස රාගද, ප්‍රීති ගීයකට ප්‍රසන්න රාගද තේරීමෙන් රසය වැඩි වේ."),
        q("රේඩියෝ හෝ රූපවාහිනී පටිගත කිරීමකදී ගායකයා මයික්‍රොෆෝනයේ 'Pop Filter' හෝ ආරක්ෂිත දුර පවත්වා ගන්නේ ඇයි?", "ප, බ වැනි පිපිරුම් ශබ්ද හා හුස්ම පහර පටිගත වීම වැළැක්වීමට", "හඬ සම්පූර්ණයෙන් නැති කිරීමට", "මුහුණ සැඟවීමට", "වාද්‍ය භාණ්ඩ වසා තැබීමට", "උච්චාරණයේදී නිකුත් වන දැඩි වායු පහරවල් මයික්‍රොෆෝනයට වැදීම පාලනය කෙරේ."),
        q("සංගීත භාණ්ඩයක් වාදනය කිරීමේදී 'නියපොතු' හා 'ඇඟිලි' නම්‍යශීලීව තබාගැනීම අත්‍යවශ්‍ය වන්නේ ඇයි?", "වේගවත් ස්වර හා පැහැදිලි නාද බාධාවකින් තොරව නිපදවීමට", "අලංකාරයට දිගට නිය වැවීමට", "භාණ්ඩය සීරීමට", "තන්තු කැඩීමට", "වයලීනයේ හා තබ්ලාවේ වම් අතේ නිය කොටට කපා පිරිසිදුව තබාගැනීම වාදනයට පහසු වේ."),
        q("වයලීනයක් හෝ සිතාරයක් පිරිසිදු කිරීමේදී වාදනයෙන් පසු අනුගමනය කළ යුතු නිවැරදි පුරුද්ද කුමක්ද?", "මෘදු වියළි රෙදි කැබැල්ලකින් තන්තු හා බඳේ දහඩිය/රෝසින් පිසදැමීම", "සබන් වතුරෙන් සේදීම", "පොල් තෙල් තවරා තැබීම", "වැලි කඩදාසියකින් මැදීම", "ඇඟිලි දහඩිය හා රෝසින් කුඩු පිසදැමීමෙන් තන්තු මලකෑම හා ලීයට හානි වීම වැළකේ."),
        q("ශ්‍රී ලංකාවේ 'ජන සංගීතය' සහ 'ශාස්ත්‍රීය සංගීතය' යන දෙකම සංගීත ශිෂ්‍යයෙකු හැදෑරිය යුත්තේ කුමක් නිසාද?", "ජාතික අනන්‍යතාවත් ශාස්ත්‍රීය ශිල්පීය පදනමත් යන දෙකම ලැබෙන බැවිනි", "එකක් අනෙකට වඩා නරක නිසා", "විභාගයට ලකුණු ගැනීමට පමණක්", "වාද්‍ය භාණ්ඩ විකිණීමට", "දේශීය හරය හා විධිමත් ස්වර-තාල න්‍යාය යන දෙඅංශයම පරිපූර්ණ සංගීතඥයෙකුට වැදගත් වේ."),
        q("ස්වර සප්තකයේ සංඛ්‍යාත විද්‍යාත්මකව අධ්‍යයනය කිරීමෙන් සිසුවෙකුට අවබෝධ වන්නේ කුමක්ද?", "සංගීතය හා භෞතික විද්‍යාව/ගණිතය අතර ඇති සමීප සබඳතාව", "සංගීතයට කිසිදු විද්‍යාත්මක පදනමක් නැති බව", "ස්වර හිතුමතේට සෑදෙන බව", "ශබ්දය ආලෝකයට වඩා වේගවත් බව", "ශ්‍රැති හා ස්වර පරතරයන් නිශ්චිත ගණිතමය සංඛ්‍යාත අනුපාත මත ගොඩනැගී ඇත."),
        q("මධ්‍ය සප්තකයේ 'පංචමය' (Pa) සහ 'ෂඩ්ජය' (Sa) අතර ඇති පරිපූර්ණ සංඛ්‍යාත අනුපාතය කුමක්ද?", "3:2 අනුපාතය", "2:1 අනුපාතය", "4:1 අනුපාතය", "1:1 අනුපාතය", "ස = 240 Hz නම්, ප = 360 Hz වන අතර එය 3:2 පරිපූර්ණ පංචම (Perfect Fifth) අනුපාතයයි."),
        q("මධ්‍ය සප්තකයේ 'ශුද්ධ මධ්‍යමය' (Ma) සහ 'ෂඩ්ජය' (Sa) අතර ඇති සංඛ්‍යාත අනුපාතය කුමක්ද?", "4:3 අනුපාතය", "3:2 අනුපාතය", "5:2 අනුපාතය", "2:1 අනුපාතය", "ස = 240 Hz නම්, ම = 320 Hz වන අතර එය 4:3 අනුපාතයට අනුරූප වේ."),
        q("තන්තුවක ආතතිය (Tension / තද බව) වැඩි කළ විට එම තන්තුවෙන් නිකුත් වන ස්වරයට කුමක් සිදුවේද?", "ස්වරය ඉහළ නගී (සංඛ්‍යාතය වැඩි වේ)", "ස්වරය පහළ බසී (සංඛ්‍යාතය අඩු වේ)", "ස්වරය වෙනස් නොවේ", "ශබ්දය සම්පූර්ණයෙන් නතර වේ", "ඛූන්ටි කරකවා තන්තුව තද කළ විට ස්වරය උස් වේ; බුරුල් කළ විට පහළ බසී."),
        q("තන්තුවක ඝනකම (Thickness) වැඩි වූ විට නිකුත් වන නාදය කවර ස්වභාවයක් ගනීද?", "ගැඹුරු පහළ ස්වරයක් (මන්ද්‍ර නාදයක්) උපදී", "ඉතා උස් ස්වරයක් උපදී", "සීනු හඬක් උපදී", "නාදයක් නොනැගේ", "සිතාරයේ හා තම්බුරාවේ ගැඹුරු ඛරජ් ස්වර සඳහා ඝනකම වැඩි පිත්තල/තඹ තන්තු යොදාගනී."),
        q("ශ්‍රව්‍ය පටිගත කිරීමකදී හා සජීවී වේදිකාවේදී 'මොනිටර් ස්පීකර්' (Stage Monitors) තැබීමේ අරමුණ කුමක්ද?", "ගායකයාට හා වාදකයන්ට තමන්ගේම හඬ හා සංගීතය පැහැදිලිව ඇසීමට", "ප්‍රේක්ෂකයන්ට පිටුපසින් ඇසීමට", "වේදිකාව සැරසීමට පමණක්", "ආලෝකය ලබාදීමට", "වේදිකාව මත සිටින ශිල්පීන්ට නිවැරදිව ශ්‍රැතිය හා තාලය පවත්වා ගැනීමට මොනිටර් උපකාරී වේ."),
        q("සුසර ගබලක් (Tuning Fork) සංගීත හා විද්‍යාගාර කටයුතුවලදී භාවිත කරන්නේ කුමක් සඳහාද?", "නිශ්චිත සම්මත ස්වර සංඛ්‍යාතයක් ලබාගැනීමට", "තබ්ලා ඇසට පහර දී සම තැබීමට", "සිතාර් පිත්තල තන්තු කපා ගැනීමට", "ස්වර ප්‍රස්තාර අකුරු ලියා ගැනීමට", "සම්මත තාරතාව පරීක්ෂා කර වාද්‍ය භාණ්ඩ සුසර කිරීමට සුසර ගබල යොදාගනී."),
        q("පෙරදිග සංගීතයේ සාම්ප්‍රදායික 'ස = 240 Hz' ස්වර පරිමාණය හා බටහිර සම්මත 'A = 440 Hz' ස්වරය අතර පවතින්නේ කුමක්ද?", "සංඛ්‍යාත මූලධර්ම මත පදනම් වූ නියමිත ස්වර සම්මතයන්ය", "සම්පූර්ණ විරුද්ධතාවකි", "කිසිදු සම්බන්ධයක් නොමැත", "විදුලි පරිපථ පමණි", "සංගීත පද්ධති දෙකෙහිම ස්ථිර නාද පදනමක් ලබාගැනීමට සම්මත සංඛ්‍යාත භාවිත කෙරේ."),
        q("'ඒකාබද්ධ රස වින්දනය' යනු ප්‍රේක්ෂකයාට කවර අත්දැකීමක් ලබාදීමද?", "ගීතයේ පද, තනුව, වාදනය හා ගායනය යන සියල්ල එක්ව විඳගැනීම", "වචන පමණක් කියවා බැලීම", "වාද්‍ය භාණ්ඩ පමණක් ඇසීම", "රූප පමණක් බැලීම", "හොඳ ගීතයක සාහිත්‍ය, ස්වර හා රිද්ම සමවාය එකවර හදවතට දැනේ."),
        q("උසස් සංගීත නිර්මාණයක 'ලය' පිළිබඳව සැලකීමේදී ශෝකජනක ගීතයකට වඩාත් ගැළපෙන්නේ කවර ලයද?", "විලම්බ හෝ මන්දගාමී මධ්‍ය ලය", "අති වේගවත් දෘත ලය", "බයිලා 6/8 ලය", "ලය විරහිත කැඩුණු රිද්මය", "දුක හා බැරෑරුම් හැඟීම් ප්‍රකාශ කිරීමට සෙමින් ගලා යන විලම්බ ලය ඉතා යෝග්‍ය වේ."),
        q("ප්‍රීතිමත් නර්තන අවස්ථාවක් හෝ උත්සවශ්‍රීයක් නිරූපණය කරන ගීතයකට වඩාත් සුදුසු වන්නේ කවර ලයද?", "මධ්‍ය හෝ දෘත ලය", "අති විලම්බ ලය", "නිහඬ විරාමය පමණක්", "අවසන් ආලාපය පමණක්", "සතුට, ජවය හා ප්‍රබෝධය ප්‍රකාශ කිරීමට වේගවත් මධ්‍ය හා දෘත ලය යොදාගනී."),
        q("ගායනයේදී 'ගමක' (Gamaka) භාවිත කිරීමෙන් සිදුවන ප්‍රධාන සේවාව කුමක්ද?", "ස්වර අතර කම්පනය හා ලාලිත්‍යය මගින් රාගයේ ප්‍රාණවත් බව මැවීම", "තාලය අවුල් කිරීම", "වචන නොඇසෙන සේ කිරීම", "භාණ්ඩයේ හඬ වසා දැමීම", "සෘජු පැතලි ස්වර වෙනුවට භාරතීය හා දේශීය ගායනයට අනන්‍ය සුන්දරත්වය ගමක තුළින් ලැබේ."),
        q("දේශීය ජන ගී ගායනා කරන විට මතු වන 'හෙළ ගැමි ලාලිත්‍යය' රැකගැනීමට කළ යුත්තේ කුමක්ද?", "සාම්ප්‍රදායික අඳෝනා හා ස්වභාවික හඬ උස් පහත් කිරීම් අනුගමනය කිරීම", "විදේශීය ඔපෙරා විලාසය ආදේශ කිරීම", "ස්වර යන්ත්‍රිකව කැපීම", "පසුබිමේ බර රොක් ඩ්‍රම්ස් වැයීම", "ජන ගීයේ ප්‍රාදේශීය නාද රටාව සහ ගැමි හඬ මෘදු බව රැකගත යුතුය."),
        q("ප්‍රායෝගික සංගීතයේදී 'තාලාවර්තනය' (Time Cycle / Avartan) යනු කුමක්ද?", "තාලයක සම සිට ඊළඟ සම දක්වා සම්පූර්ණ වන එක් වටයකි", "ගීතයේ අවසාන පදයයි", "භාණ්ඩයක් සුසර කරන කාලයයි", "වේදිකාවේ තිරය අරින වේලාවයි", "මාත්‍රා 16 ත්‍රිතාලයක 1 සිට 16 දක්වා ගොස් නැවත 1ට පැමිණීම එක් ආවර්තනයකි."),
        q("ප්‍රායෝගික වාදනයකදී තාලයක 'දුගුන්' (දෙගුණ ලය) වැයීමෙන් අදහස් කරන්නේ කුමක්ද?", "එක් මාත්‍රාවක් තුළ ස්වර හෝ බෝල් දෙක බැගින් සමානව වැයීම", "මාත්‍රා දෙකකට එක් ස්වරයක් වැයීම", "වැයීම නතර කිරීම", "හඬ දෙගුණයකින් වැඩි කිරීම", "මූලික බරාබර් ලය මෙන් දෙගුණයක වේගයෙන් එක් මාත්‍රාවකට ඒකක 2ක් වැයීම දුගුන් වේ."),
        q("තාලයක 'චෞගුන්' (සිව්ගුණ ලය) වැයීම යනු කුමක්ද?", "එක් මාත්‍රාවක් තුළ ස්වර හෝ අක්ෂර හතර බැගින් වැයීම", "මාත්‍රා හතරක් විවේක ගැනීම", "භාණ්ඩ හතරක් එකවර ගැසීම", "රාග හතරක් කලවම් කිරීම", "නිශ්චිත මාත්‍රාවක කාලය තුළ සමානව බෙදූ ස්වර 4ක් වැයීම චෞගුන් ලයකාරියයි."),
        q("වාචික පරීක්ෂණයේදී 'රාගයක වාදී ස්වරය' හඳුනාගන්නේ කෙසේදැයි ඇසුවහොත් දිය යුතු හොඳම පිළිතුර කුමක්ද?", "රාගය තුළ වැඩිපුරම යෙදෙන හා ප්‍රමුඛව නැවතී ප්‍රකාශ වන රජු බඳු ස්වරය බව", "රාගයෙන් සම්පූර්ණයෙන් ඉවත් කළ ස්වරය බව", "සප්තකයේ අවසාන ස්වරය බව", "තාලයේ ඛාලි ස්ථානය බව", "රාගයේ රසය තීරණය කරන ප්‍රධානතම ස්වරය වාදී ස්වරයයි."),
        q("සිසුන් අතර 'පාසල් තූර්ය වාදක කණ්ඩායමක්' (School Band / Orchestra) පවත්වා ගැනීමෙන් ලැබෙන ප්‍රධාන සමාජ ප්‍රතිලාභය කුමක්ද?", "විනය, කණ්ඩායම් හැඟීම, නායකත්වය හා සාමූහික වගකීම වර්ධනය වීම", "තනිවම අනෙක් අය නොතකා හැසිරීම", "අධ්‍යාපන කටයුතු අතපසු කිරීම", "ශබ්ද දූෂණය වැඩි කිරීම", "සමූහ වාදනය දරුවන්ට සමාජ කුසලතා හා විනය පුරුදු කරන විශිෂ්ට මාධ්‍යයකි."),
        q("සංගීත කාමරයක ඇති වාද්‍ය භාණ්ඩ නිසි ලෙස නඩත්තු කිරීම සිසුන්ගේ වගකීමක් වන්නේ ඇයි?", "භාණ්ඩවල කල්පැවැත්ම හා නිවැරදි නාද ගුණය දිගු කල් රැකගැනීමට", "කාමරය අගුළු දමා තැබීමට", "භාණ්ඩ භාවිත නොකර සිටීමට", "අලුත් භාණ්ඩ මිලදී ගැනීම වැළැක්වීමට පමණක්", "නිසි නඩත්තුව නිසා ඊළඟ සිසු පරපුරටත් එම වාද්‍ය භාණ්ඩ ප්‍රයෝජනයට ගත හැකිය."),
        q("ප්‍රසංගයකදී පෙරදිග හාමෝනියම් හා තබ්ලා ස්ථානගත කිරීමේදී ගායකයාට වඩාත් පහසු වන්නේ කෙසේද?", "ගායකයාගේ එක් පසෙකින් තබ්ලා වාදකයාද අනෙක් පසින් ස්වර වාදකයන්ද සිටීම", "සියලු වාදකයන් තිරයට පිටුපසින් සිටීම", "තබ්ලා වාදකයා ශාලාවේ කෙළවර සිටීම", "ගායකයා සියලු භාණ්ඩවලට පිටුපසින් සැඟවී සිටීම", "එවිට ගායකයාට හා වාදකයන්ට එකිනෙකා දැකගනිමින් නිවැරදිව සංවාදශීලීව වැයීමට හැකි වේ."),
        q("ශ්‍රී ලංකාවේ ගීත කලාවේ 'අර්ථපූර්ණ ගීතයක්' තෝරා ගැනීමේදී ශ්‍රාවකයා සැලකිලිමත් විය යුතු මූලික අංග මොනවාද?", "සාහිත්‍යමය පද රචනය, උචිත තනුව, සංගීත සංයෝජනය හා භාවපූර්ණ ගායනය", "ගීතයේ වීඩියෝ දර්ශනවල වියදම පමණක්", "අධික වේගය හා ඝෝෂාව පමණක්", "විදේශීය වචන ප්‍රමාණය", "ගුණාත්මක ගීතයක පද, තනු, වාද්‍ය සංයෝජන හා ගායනය යන අංග හතරම සුසංයෝගී වේ."),
        q("නව නිර්මාණශීලී ගීතයක් සැකසීමේදී 'තාලය තේරීම' වැදගත් වන්නේ කුමන කරුණ මතද?", "පද රචනයේ මාත්‍රා ඡන්දසට හා හැඟීමට තාලය ගැළපිය යුතු බැවින්", "ඕනෑම තාලයක් අහඹු ලෙස දැමිය හැකි බැවින්", "තබ්ලා වාදකයා කැමතිම තාලය පමණක් ගත යුතු බැවින්", "සෑම ගීතයකටම දාද්‍රා තාලය පමණක් ගැළපෙන බැවින්", "වචනවල බර හා කාව්‍යමය ගලා යෑම නිවැරදි තාලය තුළින් ඉස්මතු වේ."),
        q("ශබ්ද පරිසරයේ 'ශබ්ද දූෂණය' (Noise Pollution) සහ 'සංගීතමය නාදය' අතර ඇති ප්‍රධාන භෞතික වෙනස කුමක්ද?", "සංගීත නාදය ක්‍රමවත් හා ආවර්තිත කම්පනයක් වන අතර ඝෝෂාව අක්‍රමවත් කම්පනයකි", "සංගීත නාදයේ සංඛ්‍යාතයක් නොමැති වීම", "ඝෝෂාව රික්තයක පවා ගමන් කිරීම", "සංගීතය සැමවිටම 120 dB ට වැඩි වීම", "නියමිත ක්‍රමවත් තරංග ආකෘතියක් ඇති නාදය කනට මිහිරි වන අතර අක්‍රමවත් කම්පන ඝෝෂාවකි."),
        q("සංගීත පන්ති කාමරයක තබා ඇති 'සිතාරය' හා 'තම්බුරාව' ආරක්ෂා කිරීමට සැලකිය යුතු දේශගුණික සාධකය කුමක්ද?", "අධික තෙතමනයෙන් හා අධික වියළි හිරු රශ්මියෙන් ආරක්ෂා කිරීම", "නිතර වතුර ඉස තෙත් කර තැබීම", "හිරු එළියේ දිනපතා තබා වේලීම", "වැස්සේ තබා සේදීම", "උෂ්ණත්වය හා ආර්ද්‍රතාව අධික වෙනස් වීමෙන් ලී හා ලබු කබල් පිපිරීමට ඉඩ ඇත."),
        q("සෞන්දර්ය විෂයයක් ලෙස පෙරදිග සංගීතය හැදෑරීම මගින් සිසුවෙකු තුළ ගොඩනැගෙන 'සංස්කෘතික සංවේදීතාව' යනු කුමක්ද?", "තම උරුමය මෙන්ම සෙසු ජන කොටස්වල සංගීත කලාවන්ටද ගරු කිරීම", "වෙනත් කිසිදු සංස්කෘතියක් නොපිළිගැනීම", "හුදෙක් විභාග ලකුණු ගැන පමණක් සිතීම", "පැරණි කලා අංග අවතක්සේරු කිරීම", "විවිධ සංස්කෘතීන්හි සංගීත අගය වටහාගෙන සහජීවනයෙන් කටයුතු කිරීම මෙයින් වර්ධනය වේ."),
        q("ගුවන්විදුලි හෝ වේදිකා සංගීත වැඩසටහනක් මෙහෙයවීමේදී 'නිවේදනය' හා 'සංගීතය' ගැළපිය යුත්තේ කෙසේද?", "ගීතයේ හෝ රාගයේ පසුබිමට හා රසයට උචිත සංයමශීලී හඬකින්", "ගීතය ගයන අතරතුරම උඩින් කතා කිරීමෙන්", "සංගීතයට කිසිසේත්ම අදාළ නැති දේ කීමෙන්", "විහිළු තහළු පමණක් පැවසීමෙන්", "රසවින්දනාත්මක වැඩසටහනක නිවේදනය සංගීත අත්දැකීම වඩාත් පොහොසත් කරන්නක් විය යුතුය.")
    )
}
